insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_52_v1'
from (values
('127.297.d.1.A',3,'A local grocery store hires neighborhood teens and donates unsold food to a shelter. Which two contributions to society does this show?','["Providing jobs and supporting community needs", "Reducing choices and closing early", "Raising prices and cutting hours", "Avoiding taxes and ignoring customers"]'::jsonb,0,'Businesses contribute through employment and community support.','original'),
('127.297.d.1.A',4,'Which of these is a way a business contributes to the economy rather than only to its owners?','["Avoiding all hiring", "Paying taxes that fund public services", "Keeping profits secret", "Charging whatever it wants"]'::jsonb,1,'Taxes and wages circulate through the economy.','original'),
('127.297.d.1.B',3,'A company that sources materials responsibly and treats workers fairly is showing:','["Price fixing", "Tax avoidance", "Social responsibility", "Monopoly power"]'::jsonb,2,'Social responsibility means considering society, not just profit.','original'),
('127.297.d.1.B',4,'Why does social responsibility matter to a business'' long-term success?','["It guarantees no competition", "It removes the need for marketing", "It lowers all costs to zero", "Customers and employees tend to support companies they trust"]'::jsonb,3,'Trust builds loyalty and reputation.','original'),
('127.297.d.1.C',3,'A company that makes furniture from raw lumber is engaged in:','["Production", "Retail only", "Banking", "Insurance"]'::jsonb,0,'Producing goods is a core business activity.','original'),
('127.297.d.1.C',4,'Which pair lists two types of business activities?','["Hobbies and games", "Manufacturing and service", "Weather and sports", "Birthdays and holidays"]'::jsonb,1,'Businesses manufacture goods or provide services.','original'),
('127.297.d.1.D',3,'An organizational chart that shows departments such as marketing, finance, and operations illustrates a business''s:','["Product slogan", "Weather forecast", "Organizational design", "Tax return"]'::jsonb,2,'The chart shows how a business is structured.','original'),
('127.297.d.1.D',4,'In a functional organizational design, employees are grouped by:','["Birth month", "Favorite color", "Height", "Job function such as sales or accounting"]'::jsonb,3,'Functional design groups similar jobs.','original'),
('127.297.d.1.E',3,'A business that sells products in several countries is operating in the:','["Global environment", "Family kitchen", "School cafeteria", "Local garage"]'::jsonb,0,'Global operations cross national borders.','original'),
('127.297.d.1.E',4,'Exchange rates matter to a company that:','["Has no customers", "Buys or sells products across countries", "Sells only on one street", "Never uses money"]'::jsonb,1,'Currency values affect international prices.','original'),
('127.297.d.1.F',3,'Which is an outside factor that affects the business environment?','["The break-room snacks", "The owner''s mood", "Government regulations", "The color of the logo"]'::jsonb,2,'Laws and regulations are external factors.','original'),
('127.297.d.1.F',4,'A new competitor opens next door. A business should respond by:','["Ignoring all changes", "Closing immediately", "Lying to customers", "Adjusting its strategy to the changed environment"]'::jsonb,3,'Businesses adapt to environmental change.','original'),
('127.297.d.2.A',3,'The marketing concept says a business should focus on:','["Satisfying customer needs while earning a profit", "Copying competitors only", "Ignoring customers", "Selling at any cost"]'::jsonb,0,'Customer satisfaction drives the marketing concept.','original'),
('127.297.d.2.A',4,'A company surveys customers before designing a new product. This applies the:','["Zoning law", "Marketing concept", "Payroll cycle", "Tax code"]'::jsonb,1,'Starting with customer needs applies the concept.','original'),
('127.297.d.2.B',3,'Marketing research is a marketing function that involves:','["Paying taxes", "Building roads", "Gathering and analyzing information about customers", "Hiring staff"]'::jsonb,2,'Research supports decision making.','original'),
('127.297.d.2.B',4,'Which marketing function includes setting a product''s cost to customers?','["Market research", "Product development", "Distribution", "Pricing"]'::jsonb,3,'Pricing establishes what customers pay.','original'),
('127.297.d.3.A',4,'A company advertises in a magazine. Which P is this?','["Promotion", "Place", "Product", "Price"]'::jsonb,0,'Advertising is promotion.','original'),
('127.297.d.3.B',3,'A strategy that uses all four Ps in a coordinated plan helps a business:','["Avoid customers", "Reach its target market effectively", "Lower quality", "Confuse buyers"]'::jsonb,1,'A coordinated mix supports strategy.','original'),
('127.297.d.3.B',4,'A luxury brand uses high prices, premium stores, and elegant ads. This shows the mix:','["Contradicting itself", "Having no strategy", "Working together to support one image", "Ignoring the market"]'::jsonb,2,'Consistency across the mix builds brand image.','original'),
('127.297.d.4.A',4,'Why do businesses choose a target market instead of trying to sell to everyone?','["To raise costs", "To lose sales", "To avoid customers", "To use limited resources more effectively"]'::jsonb,3,'Focus improves efficiency.','original'),
('127.297.d.4.B',4,'A possible disadvantage of segmentation is that it can:','["Increase costs because several plans are needed", "Make products identical", "Eliminate customers", "Remove all risk"]'::jsonb,0,'More segments mean more planning.','original'),
('127.297.d.4.C',3,'Dividing customers by age, income, and gender is which kind of segmentation?','["Psychographic", "Demographic", "Behavioral", "Geographic"]'::jsonb,1,'Age, income, and gender are demographics.','original'),
('127.297.d.4.C',4,'Dividing customers by climate or region is which kind of segmentation?','["Psychographic", "Demographic", "Geographic", "Behavioral"]'::jsonb,2,'Location-based grouping is geographic.','original'),
('127.297.d.4.D',3,'Marketing planning typically begins with:','["Choosing a font", "Printing fliers", "Hiring a mascot", "Analyzing the market and setting objectives"]'::jsonb,3,'Plans start with analysis and goals.','original'),
('127.297.d.4.D',4,'A marketing plan usually includes objectives, strategies, a budget, and:','["A way to evaluate results", "A rumor", "A joke", "A secret"]'::jsonb,0,'Evaluation closes the loop.','original'),
('127.297.d.5.A',3,'A store sells 4 shirts at $15 each. The total sales are:','["$19", "$60", "$75", "$45"]'::jsonb,1,'4 x 15 = 60.','original'),
('127.297.d.5.A',4,'A delivery takes 2.5 hours at 40 miles per hour. Distance traveled is:','["16 miles", "80 miles", "100 miles", "42.5 miles"]'::jsonb,2,'40 x 2.5 = 100.','original'),
('127.297.d.5.B',3,'A bar graph shows sales were highest in December. A marketer should consider:','["Lowering quality", "Closing in December", "Ignoring the graph", "Increasing holiday promotions"]'::jsonb,3,'Data informs decisions.','original'),
('127.297.d.5.B',4,'A line graph of sales falls for three straight months. A good next step is to:','["Investigate causes and adjust the strategy", "Raise all costs", "Celebrate", "Do nothing"]'::jsonb,0,'Trends call for analysis.','original'),
('127.297.d.5.C',3,'Profit equals:','["Costs minus revenue", "Revenue minus costs", "Revenue plus costs", "Revenue times costs"]'::jsonb,1,'Profit = revenue − costs.','original'),
('127.297.d.5.C',4,'Fixed costs are $2,000. Each unit sells for $20 and costs $10 to make. Break-even units equal:','["20", "400", "200", "100"]'::jsonb,2,'2,000 / (20 − 10) = 200.','original'),
('127.297.d.5.D',3,'What is 15% of $80?','["$20", "$15", "$8", "$12"]'::jsonb,3,'0.15 x 80 = 12.','original'),
('127.297.d.5.D',4,'A $50 item is on sale for 30% off. The sale price is:','["$35", "$30", "$15", "$20"]'::jsonb,0,'50 x 0.70 = 35.','original'),
('127.297.d.5.E',3,'A store expects about 297 customers and rounds to the nearest hundred. The estimate is:','["290", "300", "200", "250"]'::jsonb,1,'297 rounds to 300.','original'),
('127.297.d.5.E',4,'A marketer estimates the cost of 49 items at $9.95 each. A reasonable estimate is:','["About $5,000", "About $5", "About $500", "About $50"]'::jsonb,2,'50 x 10 = 500.','original'),
('127.297.d.5.F',3,'A taxi charges $3 plus $2 per mile. Which equation models the cost C for m miles?','["C = 5m", "C = 2 + 3", "C = 3m + 2", "C = 3 + 2m"]'::jsonb,3,'Flat fee plus rate times miles.','original'),
('127.297.d.5.F',4,'A subscription costs $10 a month plus a $15 setup fee. Total cost after n months is:','["10n + 15", "10 + 15 + n", "25n", "15n + 10"]'::jsonb,0,'Rate times months plus setup.','original'),
('127.297.d.5.G',3,'Sales went from $200 to $260 in one month. The change in sales is:','["$460", "$60", "$130", "$200"]'::jsonb,1,'260 − 200 = 60.','original'),
('127.297.d.5.G',4,'Sales rose $90 over 3 months. The average rate of change per month is:','["$93", "$270", "$30", "$3"]'::jsonb,2,'90 / 3 = 30.','original'),
('127.297.d.6.A',3,'Good interpersonal skills in a team include:','["Interrupting", "Blaming others", "Avoiding work", "Listening and sharing responsibility"]'::jsonb,3,'Teams need cooperation.','original'),
('127.297.d.6.A',4,'A team-building activity helps members to:','["Learn to trust and communicate", "Work alone", "Compete harshly", "Avoid conflict by quitting"]'::jsonb,0,'Trust improves teamwork.','original'),
('127.297.d.6.B',3,'A short-term goal is one that you hope to reach:','["After retirement", "Within days or weeks", "After decades", "Never"]'::jsonb,1,'Short-term goals are near.','original'),
('127.297.d.6.C',3,'A time-management principle is to:','["Avoid deadlines", "Do tasks randomly", "Plan ahead and prioritize tasks", "Wait for inspiration"]'::jsonb,2,'Planning improves time use.','original'),
('127.297.d.6.C',4,'Breaking a big project into smaller scheduled steps helps with:','["Typing speed", "Painting", "Memorizing slogans", "Time management"]'::jsonb,3,'Chunking supports planning.','original'),
('127.297.d.6.D',3,'Participating in a student career organization helps you develop:','["Leadership and career skills", "Sleeping habits", "Cooking skills only", "Weather skills"]'::jsonb,0,'CTSOs build leadership.','original'),
('127.297.d.6.D',4,'A student attends a career fair to:','["Avoid work", "Learn about careers and meet employers", "Skip class only", "Win a prize only"]'::jsonb,1,'Career events inform choices.','original'),
('127.297.d.7.A',3,'Which is a social media trend in marketing?','["Faxing flyers", "Printing phone books", "Using short videos to reach customers", "Sending telegrams"]'::jsonb,2,'Short video is a current trend.','original'),
('127.297.d.7.A',4,'Influencer marketing is when a business:','["Avoids social media", "Fires staff", "Prints coupons only", "Partners with popular social media personalities to promote products"]'::jsonb,3,'Influencers extend reach.','original'),
('127.297.d.7.B',3,'Technology impacts business by:','["Speeding communication and automating tasks", "Making all jobs identical", "Eliminating all customers", "Stopping sales"]'::jsonb,0,'Technology changes operations.','original'),
('127.297.d.7.B',4,'Online ordering systems mainly help a store to:','["Reduce internet access", "Serve customers 24 hours a day", "Raise confusion", "Close its doors"]'::jsonb,1,'E-commerce extends hours.','original'),
('127.297.d.7.C',3,'For a more accurate web search, you should use:','["Random letters", "Only emojis", "Specific keywords", "One vague word"]'::jsonb,2,'Specific terms narrow results.','original'),
('127.297.d.7.C',4,'Before trusting a web source for marketing data, check the:','["Color scheme", "Font size", "Number of ads", "Credibility and date of the source"]'::jsonb,3,'Evaluate sources.','original'),
('127.297.d.7.D',3,'Word-processing software is best used to create a:','["Business letter or report", "Photo edit only", "Database query", "Spreadsheet formula"]'::jsonb,0,'Word processors handle text documents.','original'),
('127.297.d.7.D',4,'A marketer uses a mail merge to:','["Block email", "Send personalized letters to many customers", "Change fonts only", "Delete files"]'::jsonb,1,'Mail merge personalizes bulk mail.','original'),
('127.297.d.7.E',3,'A customer database can be used to:','["Cook meals", "Print posters only", "Store and search customer information", "Delete employees"]'::jsonb,2,'Databases organize records.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
